# Kaggle runner for swegemma experiments.
# Generated by build_kernel.py: the RUN dict and SUBMISSION_FILES are filled in there.
# Runs a submission on a subset of the public tasks and saves results, traces and
# patches to /kaggle/working/<run_name>.

import asyncio
import glob
import importlib
import json
import logging
import os
import re
import shutil
import subprocess
import sys
import time
import traceback
from pathlib import Path

RUN = __RUN__
SUBMISSION_FILES = __SUBMISSION_FILES__

for k, v in {
    'TRANSFORMERS_NO_TF': '1', 'TRANSFORMERS_NO_FLAX': '1', 'TRANSFORMERS_OFFLINE': '1',
    'VLLM_NO_USAGE_STATS': '1', 'VLLM_WORKER_MULTIPROC_METHOD': 'spawn',
    'VLLM_ENGINE_READY_TIMEOUT_S': '1200', 'VLLM_MEMORY_PROFILER_ESTIMATE_CUDAGRAPHS': '1',
    'NCCL_DEBUG': 'WARN', 'LITELLM_LOCAL_MODEL_COST_MAP': 'True', 'LITELLM_TELEMETRY': 'False',
    'LITELLM_LOG': 'WARNING', 'PYTORCH_CUDA_ALLOC_CONF': 'expandable_segments:True',
    'OTEL_SDK_DISABLED': 'true', 'OTEL_PYTHON_DISABLED': 'true',
}.items():
    os.environ[k] = v
os.environ.setdefault('OPENAI_API_KEY', 'EMPTY')
os.environ.setdefault('LOCAL_API_KEY', 'EMPTY')


def quiet_logs():
    for name in ('LiteLLM', 'LiteLLM Router', 'LiteLLM Proxy', 'litellm', 'httpx', 'httpcore',
                 'openai', 'urllib3', 'opentelemetry', 'opentelemetry.context'):
        lg = logging.getLogger(name)
        lg.setLevel(logging.WARNING)
        if 'litellm' in name.lower():
            lg.propagate = False
            lg.handlers.clear()


quiet_logs()
T0 = time.time()
print('python', sys.version, flush=True)


def log(msg):
    print(f'[{time.time() - T0:7.0f}s] {msg}', flush=True)


# ---- 1. Install the harness wheelhouse (same steps as the official starter notebook)
WHEELHOUSE_DIR = Path('/kaggle/input/datasets/metric/gemma-4-developer-agent-wheelhouse')
if not WHEELHOUSE_DIR.exists():
    cands = glob.glob('/kaggle/input/**/gemma-4-developer-agent-wheelhouse', recursive=True)
    WHEELHOUSE_DIR = Path(cands[0])
for pat in ('/usr/local/lib/python*/dist-packages/*cutlass*.pth',
            '/usr/local/lib/python*/site-packages/*cutlass*.pth'):
    for pth in glob.glob(pat):
        try:
            os.unlink(pth)
        except OSError:
            pass
tmp_whl = Path('/tmp/wheelhouse')
tmp_whl.mkdir(parents=True, exist_ok=True)
for w in WHEELHOUSE_DIR.glob('*.whl'):
    if 'cutlass' in w.name.lower():
        continue
    name = w.name.replace('cu128', '+cu128') if ('cu128' in w.name and '+' not in w.name) else w.name
    target = tmp_whl / name
    if not target.exists():
        try:
            os.symlink(w, target)
        except OSError:
            shutil.copyfile(w, target)
subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', '--no-deps', '--force-reinstall',
                *sorted(str(w) for w in tmp_whl.glob('*.whl'))], check=True)
importlib.invalidate_caches()
quiet_logs()
log('wheelhouse installed')

# ---- 2. Write the submission directory
DATA_DIR = Path('/kaggle/input/competitions/gemma-4-developer-agent')
if not DATA_DIR.exists():
    DATA_DIR = Path(glob.glob('/kaggle/input/**/gemma-4-developer-agent/tasks.jsonl', recursive=True)[0]).parent
WORK = Path('/kaggle/working')
OUT = WORK / RUN['name']
OUT.mkdir(parents=True, exist_ok=True)
AGENT_DIR = WORK / 'submission'
if AGENT_DIR.exists():
    shutil.rmtree(AGENT_DIR)
if SUBMISSION_FILES:
    for rel, content in SUBMISSION_FILES.items():
        p = AGENT_DIR / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content, encoding='utf-8')
else:  # official sample submission, switched to RUN['model'] like the starter notebook does
    shutil.copytree(DATA_DIR / 'sample_submission', AGENT_DIR)
    if RUN['model'] != 'gemma-4-31b-it-qat-w4a16-ct':
        for yp in [AGENT_DIR / 'agent.yaml', *sorted((AGENT_DIR / 'sub_agents').glob('*.yaml'))]:
            t = yp.read_text(encoding='utf-8')
            t = re.sub(r'^(\s*model:\s*).*$', rf"\g<1>{RUN['model']}", t, flags=re.M)
            t = re.sub(r'^\s*adapter:\s*.*\n?', '', t, flags=re.M)
            yp.write_text(t, encoding='utf-8')
        shutil.rmtree(AGENT_DIR / 'adapters', ignore_errors=True)
shutil.copytree(AGENT_DIR, OUT / 'submission', dirs_exist_ok=True)

# ---- 3. Optionally save harness sources (to read the trace schema offline)
if RUN.get('dump_sources'):
    import swegemma, adk_submission, adk_eval_core  # noqa: E401
    for mod in (swegemma, adk_submission, adk_eval_core):
        src = Path(mod.__file__).parent
        shutil.copytree(src, OUT / 'sources' / src.name, dirs_exist_ok=True,
                        ignore=shutil.ignore_patterns('__pycache__', '*.so'))
    log('harness sources saved')

# ---- 4. Start vLLM
import litellm  # noqa: E402
import torch  # noqa: E402
from adk_submission import VllmConfig, VllmServer, discover_adapters  # noqa: E402
from adk_submission.discovery import discover_declared_models  # noqa: E402
from swegemma.config import ALLOWED_ADAPTER_EXTENSIONS  # noqa: E402

litellm.drop_params = True
declared = discover_declared_models(AGENT_DIR)
assert len(declared) == 1, declared
model = next(iter(declared))
MODEL_PATH = Path(f'/kaggle/input/models/google/gemma-4/other/{model}/2')
if not MODEL_PATH.exists():
    MODEL_PATH = Path(glob.glob(f'/kaggle/input/**/{model}/2', recursive=True)[0])
adapters = discover_adapters(str(AGENT_DIR), adapter_extensions=ALLOWED_ADAPTER_EXTENSIONS)
adapter_map = getattr(adapters, 'adapters', None) or {}
ranks = [r for i in adapter_map.values() if (r := getattr(i, 'rank', None))]
gpus = torch.cuda.device_count() if torch.cuda.is_available() else 1
tp = 4 if gpus >= 4 else (2 if gpus >= 2 else 1)
extra = {'gemma-4-12b-it-qat-w4a16-ct': (
    '--hf-overrides', '{"architectures": ["Gemma4ForCausalLM"], "model_type": "gemma4"}')}
server = VllmServer(VllmConfig(
    model=str(MODEL_PATH), port=8000, host='127.0.0.1', tool_call_parser='gemma4',
    reasoning_parser='gemma4', max_model_len=32768,
    dtype='bfloat16' if (torch.cuda.is_available() and torch.cuda.is_bf16_supported()) else 'auto',
    gpu_memory_utilization=0.90, enable_auto_tool_choice=True, enable_lora=bool(adapter_map),
    max_loras=max(1, len(adapter_map)), max_lora_rank=max(ranks) if ranks else 128,
    scheduler_reserve_full_isl=False, tensor_parallel_size=tp, startup_timeout=60 * 20,
    extra_args=extra.get(model, ()),
), adapter_manifest=adapters)
server.start()
models = server.create_model_registry(aliases=[model], model_prefix='openai/',
                                      api_key=os.environ['LOCAL_API_KEY'])
log(f'vLLM up: {model} tp={tp} gpus={gpus}')

# ---- 5. Evaluate the task subset
from google.adk.agents.context_cache_config import ContextCacheConfig  # noqa: E402
from google.adk.apps._configs import EventsCompactionConfig  # noqa: E402
from swegemma.config import EvalConfig, build_submission_limits  # noqa: E402
from swegemma.evaluate import Evaluator  # noqa: E402
from swegemma.models import load_tasks  # noqa: E402

tasks = load_tasks(DATA_DIR / 'tasks.jsonl')
ids = RUN.get('task_ids')
subset = [t for t in tasks if t.instance_id in set(ids)] if ids else tasks[::RUN.get('stride', 1)]
subset = subset[:RUN.get('limit', len(subset))]
log(f'{len(subset)} tasks: {[t.instance_id for t in subset]}')

limits, gen_constraints = build_submission_limits()
b = RUN['budget']
cfg = EvalConfig(
    tasks_path=DATA_DIR / 'tasks.jsonl', snapshots_dir=DATA_DIR / 'snapshots',
    results_dir=OUT / 'results', submission_dir=AGENT_DIR, models=models, sandbox='subprocess',
    timeout_seconds=b['timeout_seconds'], verification_timeout_seconds=300,
    max_time_minutes=b['max_time_minutes'], max_tool_calls=b['max_tool_calls'],
    max_turns=b['max_turns'], limits=limits, generation_constraints=gen_constraints,
    adapter_manifest=adapters,
    context_cache_config=ContextCacheConfig(min_tokens=2048, ttl_seconds=1800, cache_intervals=10),
    events_compaction_config=EventsCompactionConfig(
        compaction_interval=15, overlap_size=2, token_threshold=14336, event_retention_size=5),
    graph_dir=str(DATA_DIR / 'graphs'), embeddings_dir=str(DATA_DIR / 'embeddings'),
    wheels_dir=DATA_DIR / 'wheels', verbose=False,
)
evaluator = Evaluator(cfg)
summary_path = OUT / 'run_results.jsonl'


def to_jsonable(obj):
    for attr in ('model_dump', 'dict'):
        if hasattr(obj, attr):
            try:
                return getattr(obj, attr)(mode='json') if attr == 'model_dump' else obj.dict()
            except Exception:
                pass
    return {k: str(v) for k, v in vars(obj).items()} if hasattr(obj, '__dict__') else str(obj)


async def run_all():
    sem = asyncio.Semaphore(RUN.get('concurrency', 1))

    async def one(idx, task):
        async with sem:
            t1 = time.time()
            rec = {'instance_id': task.instance_id, 'repo': task.repo}
            try:
                res = await evaluator.evaluate_task(task=task, task_index=idx, total_tasks=len(subset))
                rec.update(to_jsonable(res) if not isinstance(res, dict) else res)
            except Exception as e:  # keep going: one broken task must not kill the run
                rec['runner_error'] = f'{type(e).__name__}: {e}'
                rec['runner_traceback'] = traceback.format_exc()
            rec['wall_seconds'] = time.time() - t1
            with summary_path.open('a', encoding='utf-8') as f:
                f.write(json.dumps(rec, default=str) + '\n')
            log(f"{task.instance_id}: resolved={rec.get('resolved')} "
                f"tool_calls={rec.get('tool_calls')} err={rec.get('runner_error')}")

    await asyncio.gather(*(one(i, t) for i, t in enumerate(subset, start=1)))

asyncio.run(run_all())
server.stop()

rows = [json.loads(line) for line in summary_path.read_text(encoding='utf-8').splitlines()]
solved = sum(1 for r in rows if r.get('resolved'))
meta = {'run': RUN, 'model': model, 'tasks': len(rows), 'resolved': solved,
        'resolution_rate': solved / max(1, len(rows)), 'wall_seconds': time.time() - T0}
(OUT / 'run_meta.json').write_text(json.dumps(meta, indent=2, default=str), encoding='utf-8')
log(f'done: {solved}/{len(rows)} resolved')
